CREATE TABLE IF NOT EXISTS gis_analysis_executions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES gis_analysis_requests(id) ON DELETE CASCADE, asset_id uuid NOT NULL REFERENCES continental_assets(id) ON DELETE CASCADE, execution_status text NOT NULL DEFAULT 'Queued', started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, engine_version text NOT NULL DEFAULT '1.0', findings_count integer NOT NULL DEFAULT 0, blocker_count integer NOT NULL DEFAULT 0, warning_count integer NOT NULL DEFAULT 0, summary text);
CREATE TABLE IF NOT EXISTS gis_readiness_impacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), finding_id uuid NOT NULL REFERENCES gis_analysis_findings(id) ON DELETE CASCADE, impact_code text NOT NULL, impact_status text NOT NULL DEFAULT 'Proposed', readiness_dimension text, blocking boolean NOT NULL DEFAULT false, rationale text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_gis_executions_asset ON gis_analysis_executions(asset_id,started_at DESC);
CREATE INDEX IF NOT EXISTS idx_gis_impacts_finding ON gis_readiness_impacts(finding_id,blocking);